    @Override public void onCreate(Bundle state){INK=foreground();MUTED=secondary();BACK=background();LINE=night()?0xFF35373D:0xFFE6E6ED;goals=getSharedPreferences("goals",MODE_PRIVATE);super.onCreate(state);getWindow().setStatusBarColor(BACK);getWindow().setNavigationBarColor(surface());getWindow().getDecorView().setSystemUiVisibility(night()?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);}
    String deepCopy(String text){if(!deepMode())return text;switch(text){case "오늘의 건강 요약":return "오늘도 네 편이야 ♡";case "나를 챙긴 순간,\n하루에 쌓이고 있어요":return "약부터 확인하고,\n네 속도로 가자.";case "오늘의 마음을 천천히 살펴봐요":return "예쁘게 정리 안 해도 돼. 네 마음 그대로.";case "하루하루 쌓이는 나의 변화":return "네가 남긴 순간, 여기 다 있어.";case "내 몸의 변화를 한눈에":return "마음도 몸도 네 속도로 챙기자.";default:return text;}}
    float sp(float n){return n*getResources().getDisplayMetrics().scaledDensity;}
    int accent(String k){switch(k){case "마음":case "수면":return PURPLE;case "체중":return CORAL;case "운동":return TEAL;default:return BLUE;}}
    int pale(int c){if(night())return Color.rgb((Color.red(c)+60)/4,(Color.green(c)+64)/4,(Color.blue(c)+80)/4);return Color.rgb((Color.red(c)+2295)/10,(Color.green(c)+2295)/10,(Color.blue(c)+2295)/10);}
    String key(String k){switch(k){case "마음":return "mood";case "체중":return "weight";case "운동":return "exercise";case "수면":return "sleep";default:return "water";}}
    double goal(String k,double fallback){return Double.longBitsToDouble(goals.getLong(k,Double.doubleToLongBits(fallback)));}
    String formatDate(long t,String p){return new SimpleDateFormat(p,Locale.KOREA).format(new Date(t));}
    long day(long t){Calendar c=Calendar.getInstance();c.setTimeInMillis(t);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}
    long ago(int n){Calendar c=Calendar.getInstance();c.setTimeInMillis(day(System.currentTimeMillis()));c.add(Calendar.DAY_OF_YEAR,-n);return c.getTimeInMillis();}
    long monday(){Calendar c=Calendar.getInstance();c.setTimeInMillis(ago(0));c.add(Calendar.DAY_OF_YEAR,-(c.get(Calendar.DAY_OF_WEEK)+5)%7);return c.getTimeInMillis();}
    double sum(String kind,long start){double n=0;for(JSONObject e:entries)if(kind.equals(e.optString("kind"))&&e.optLong("date")>=start&&e.optLong("date")<=System.currentTimeMillis())n+=e.optDouble("value");return n;}
    double maxValue(String k){switch(k){case "마음":return 5;case "체중":return 500;case "운동":return 1440;case "수면":return 24;case "걸음":return 1000000;default:return 20000;}}
    LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    TextView tx(String s,int size,int c,boolean bold){TextView t=new TextView(this);t.setText(deepCopy(s));t.setTextSize(size);t.setTextColor(c);t.setTypeface(bold?Typeface.create(Typeface.DEFAULT,Typeface.BOLD):Typeface.DEFAULT);t.setIncludeFontPadding(false);t.setLineSpacing(dp(3),1);t.setFontFeatureSettings("tnum");return t;}
    void gap(LinearLayout l,int h){l.addView(new View(this),new LinearLayout.LayoutParams(1,dp(h)));}
    void section(String s){gap(page,20);page.addView(tx(s,19,INK,true));gap(page,12);}
    void tap(View v,int c,Runnable r){v.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x16377CF6),bg(c,28),bg(surface(),28)));v.setOnClickListener(w->r.run());}
    LinearLayout card(LinearLayout parent){LinearLayout c=col();c.setPadding(dp(20),dp(18),dp(20),dp(18));c.setBackground(bg(surface(),22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(12));parent.addView(c,p);return c;}
    Button btn(String s,int c,boolean fill,String desc,Runnable action){Button b=new Button(this);b.setTag("galaxy-action");b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setTextColor(fill?(deepMode()&&c==BLUE?Color.BLACK:Color.WHITE):c);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));boolean tabStyle=desc.startsWith("filter-")||desc.startsWith("range-");boolean period=desc.startsWith("journal-days-");android.graphics.drawable.Drawable shape;if(tabStyle){b.setTextColor(fill?INK:MUTED);android.graphics.drawable.LayerDrawable layers=new android.graphics.drawable.LayerDrawable(new android.graphics.drawable.Drawable[]{bg(Color.TRANSPARENT,0),bg(fill?INK:Color.TRANSPARENT,0)});layers.setLayerInset(1,dp(12),dp(44),dp(12),0);shape=layers;}else shape=bg(period?(fill?surface():Color.TRANSPARENT):(fill?c:pale(c)),period?14:24);if(period)b.setTextColor(fill?INK:MUTED);b.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x16377CF6),shape,bg(surface(),24)));b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setPadding(dp(10),dp(8),dp(10),dp(8));b.setStateListAnimator(null);b.setContentDescription(desc);b.setOnClickListener(v->action.run());return b;}

    void full(LinearLayout l,String s,int c,boolean fill,String desc,Runnable action){l.addView(btn(s,c,fill,desc,action),new LinearLayout.LayoutParams(-1,dp(50)));}
    void heading(String title,String sub){String name=sub.equals("MY JOURNAL")?"기록":sub.equals("MIND CARE")?"마음":sub.equals("BODY CARE")?"건강":title;LinearLayout hero=col();hero.setGravity(Gravity.CENTER);hero.setMinimumHeight(dp(Math.max(160,Math.min(240,(int)(getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density*0.27f)))));TextView heading=tx(name,38,INK,false);heading.setGravity(Gravity.CENTER);heading.setContentDescription("galaxy-page-title");hero.addView(heading);gap(hero,10);TextView subtitle=tx(sub.equals("MY JOURNAL")?"하루하루 쌓이는 나의 변화":sub.equals("MIND CARE")?"오늘의 마음을 천천히 살펴봐요":sub.equals("BODY CARE")?"내 몸의 변화를 한눈에":sub,14,MUTED,false);subtitle.setGravity(Gravity.CENTER);hero.addView(subtitle);page.addView(hero);gap(page,16);}

