    void task(LinearLayout l,String s,String kind){boolean done=latest(kind,true)!=null;LinearLayout r=row();r.setPadding(0,dp(11),0,dp(11));r.addView(tx(done?"✓":"○",19,done?BLUE:MUTED,true),new LinearLayout.LayoutParams(dp(30),-2));r.addView(tx(s,14,done?MUTED:INK,false),new LinearLayout.LayoutParams(0,-2,1));r.addView(tx(done?"완료":"+",13,done?BLUE:MUTED,true));r.setOnClickListener(v->record(kind));l.addView(r);}
    ArrayList<JSONObject> daily(String kind,int days){TreeMap<Long,JSONObject> map=new TreeMap<>();for(JSONObject e:entries)if(kind.equals(e.optString("kind"))&&e.optLong("date")>=ago(days-1)){long t=day(e.optLong("date"));if(!map.containsKey(t))map.put(t,e);}return new ArrayList<>(map.values());}
    void empty(LinearLayout l,String title,String sub){gap(l,14);l.addView(tx(title,14,MUTED,true));gap(l,6);l.addView(tx(sub,12,MUTED,false));gap(l,14);}
