    void fillMoodDiary(){moodResults.removeAllViews();String needle=moodQuery.trim().toLowerCase(Locale.KOREA);long cutoff=ago(moodDays-1),now=System.currentTimeMillis();int n=0;for(JSONObject e:entries)if("마음".equals(e.optString("kind"))&&e.optLong("date")>=cutoff&&e.optLong("date")<=now&&e.optString("note").toLowerCase(Locale.KOREA).contains(needle)){if(n++<100){moodResults.addView(tx(formatDate(e.optLong("date"),"M월 d일 EEEE"),12,MUTED,false));entryCard(moodResults,e);}}TextView count=tx(n+"개 기록 · 최근 "+moodDays+"일"+(n>100?" · 최근 100개 표시":""),12,MUTED,false);count.setContentDescription("mood-diary-count");moodResults.addView(count,0);if(n==0)empty(moodResults,"일치하는 마음 기록이 없어요","검색어나 기간을 바꿔보세요.");}
    final Runnable breatheTick=new Runnable(){public void run(){if(!breathing)return;long elapsed=breathElapsed+SystemClock.elapsedRealtime()-breathStart;if(elapsed>=60000){breathElapsed=60000;breathing=false;breathLabel.setText("잘 쉬었어요");breathButton.setText("다시 시작");breathRing.set(1,"✓","완료");return;}int s=(int)(elapsed/1000);breathLabel.setText(s%10<4?"천천히 들이쉬기":"편안하게 내쉬기");breathRing.set(elapsed/60000f,""+(60-s),"초 남음");handler.postDelayed(this,150);}};
